-- Q9: Math MCQ Easy — Algebra / Linear Equations in One Variable
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J81B4A', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $2x + 5 = 19$, what is the value of $x$?', NULL, '[{"key":"A","text":"7"},{"key":"B","text":"14"},{"key":"C","text":"12"},{"key":"D","text":"-7"}]'::jsonb, 'A', NULL, E'The correct answer is A. Subtract 5 from both sides to get $2x = 14$. Then divide both sides by 2 to find $x = 7$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q10: Math Grid-in Medium — Algebra / Linear Equations in One Variable
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ENMJN4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ if $3(2x - 4) + 5 = 23$?', NULL, '[]'::jsonb, '5', ARRAY['5'], E'The correct answer is 5. First distribute: $6x - 12 + 5 = 23$. Combine like terms: $6x - 7 = 23$. Add 7 to both sides: $6x = 30$. Divide by 6: $x = 5$.', NULL, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q11: Math MCQ Hard — Algebra / Linear Equations in One Variable
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JROGGR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A contractor charges a flat fee of $\\$120$ plus $\\$45$ per hour of labor. If the total charge for a job was $\\$570$, how many hours of labor were required?', NULL, '[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"12"},{"key":"D","text":"15"}]'::jsonb, 'B', NULL, E'The correct answer is B. Let $h$ represent the number of hours. The total charge is modeled by $45h + 120 = 570$. Subtracting 120 from both sides gives $45h = 450$. Dividing both sides by 45 yields $h = 10$. Option A results from dividing 570 by 45 and rounding down without subtracting the flat fee. Option C comes from subtracting 120 but dividing by the wrong rate. Option D results from dividing the full amount by the hourly rate without accounting for the flat fee.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q12: Math MCQ Medium — Algebra / Linear Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S6TEHQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the $y$-intercept of the line represented by $3x - 5y = 20$?', NULL, '[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$\\\\dfrac{20}{3}$"},{"key":"D","text":"$\\\\dfrac{3}{5}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Rewrite the equation in slope-intercept form by solving for $y$: subtract $3x$ from both sides to get $-5y = -3x + 20$, then divide by $-5$ to obtain $y = \\dfrac{3}{5}x - 4$. The $y$-intercept is $-4$. Option B is a sign error from incorrectly handling the negative coefficient. Option C results from setting $y = 0$ and solving for $x$ instead. Option D confuses the slope with the intercept.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q13: Math Grid-in Hard — Algebra / Linear Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYVX9I', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line is perpendicular to $y = \\dfrac{2}{3}x + 1$ and passes through the point $(6, 4)$. What is the $y$-intercept of this line?', NULL, '[]'::jsonb, '13', ARRAY['13'], E'The correct answer is 13. The slope of the given line is $\\dfrac{2}{3}$, so the slope of any perpendicular line is the negative reciprocal, $-\\dfrac{3}{2}$. Using point-slope form with the point $(6, 4)$: $y - 4 = -\\dfrac{3}{2}(x - 6)$. Distributing: $y - 4 = -\\dfrac{3}{2}x + 9$. Adding 4 to both sides: $y = -\\dfrac{3}{2}x + 13$. The $y$-intercept is $13$.', NULL, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q14: Math MCQ Easy — Algebra / Linear Functions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SQVF4T', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A bakery models its daily production cost in dollars with the function $C(x) = 8x + 50$, where $x$ is the number of cakes produced. What does the number $8$ represent in this function?', NULL, '[{"key":"A","text":"The cost per cake produced"},{"key":"B","text":"The total number of cakes produced"},{"key":"C","text":"The fixed daily operating cost"},{"key":"D","text":"The total daily production cost"}]'::jsonb, 'A', NULL, E'The correct answer is A. In the function $C(x) = 8x + 50$, the coefficient of $x$ represents the rate of change, which is the additional cost for each cake produced. The constant $50$ represents the fixed cost, not the coefficient $8$. Option C confuses the slope with the $y$-intercept.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q15: Math MCQ Medium — Algebra / Linear Functions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2916ZRH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'Two phone plans are modeled by the functions $f(x) = 25x + 40$ and $g(x) = 15x + 90$, where $x$ is the number of months. After how many months will the two plans have the same total cost?', NULL, '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"7"},{"key":"D","text":"10"}]'::jsonb, 'B', NULL, E'The correct answer is B. Set the two functions equal: $25x + 40 = 15x + 90$. Subtract $15x$ from both sides: $10x + 40 = 90$. Subtract 40: $10x = 50$. Divide by 10: $x = 5$. At $x = 5$, both plans cost $\\$165$. Option A results from an arithmetic error when combining terms. Option D comes from dividing 90 + 40 by the difference in slopes incorrectly.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q16: Math MCQ Easy — Algebra / Linear Inequalities in One or Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z94RTO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following represents all values of $x$ that satisfy $3x - 7 < 14$?', NULL, '[{"key":"A","text":"$x < 7$"},{"key":"B","text":"$x > 7$"},{"key":"C","text":"$x < \\\\dfrac{7}{3}$"},{"key":"D","text":"$x > \\\\dfrac{7}{3}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Add 7 to both sides: $3x < 21$. Divide both sides by 3: $x < 7$. Option B incorrectly reverses the inequality direction. Option C results from dividing 7 by 3 without first adding 7 to both sides.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q17: Math MCQ Hard — Algebra / Linear Inequalities in One or Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RV5VPN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A manufacturer requires that the temperature $T$, in degrees Celsius, of a chemical solution satisfy $-2 \\leq \\dfrac{3T - 9}{3} \\leq 5$. Which of the following correctly describes the allowable range of temperatures?', NULL, '[{"key":"A","text":"$1 \\\\leq T \\\\leq 8$"},{"key":"B","text":"$-1 \\\\leq T \\\\leq 6$"},{"key":"C","text":"$1 \\\\leq T \\\\leq 6$"},{"key":"D","text":"$3 \\\\leq T \\\\leq 14$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Simplify the compound inequality $-2 \\leq \\dfrac{3T - 9}{3} \\leq 5$. The fraction simplifies to $T - 3$, giving $-2 \\leq T - 3 \\leq 5$. Add 3 to all three parts: $1 \\leq T \\leq 8$. Option B results from adding 1 instead of 3. Option C comes from simplifying the fraction correctly but only adding 3 to one side. Option D results from multiplying by 3 instead of simplifying the fraction first, then adding 3.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q18: Math MCQ Medium — Algebra / Systems of Two Linear Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28ODSJL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'What is the value of $x$ in the solution to the system of equations below?\n$$2x + y = 7$$\n$$x - y = 2$$', NULL, '[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"9"}]'::jsonb, 'B', NULL, E'The correct answer is B. Add the two equations to eliminate $y$: $(2x + y) + (x - y) = 7 + 2$, which simplifies to $3x = 9$. Dividing by 3 gives $x = 3$. Substituting back: $y = 7 - 2(3) = 1$. Option A is the value of $y$, not $x$. Option C results from subtracting the equations instead of adding. Option D is the sum $3x$ before dividing.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q19: Math Grid-in Hard — Algebra / Systems of Two Linear Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7MRWF', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'A store sells notebooks for $\\$3$ each and pens for $\\$2$ each. A customer buys a total of 14 items and spends $\\$33$. How many notebooks does the customer buy?', NULL, '[]'::jsonb, '5', ARRAY['5'], E'The correct answer is 5. Let $n$ be the number of notebooks and $p$ be the number of pens. The system of equations is $n + p = 14$ and $3n + 2p = 33$. From the first equation, $p = 14 - n$. Substituting into the second equation: $3n + 2(14 - n) = 33$, which simplifies to $3n + 28 - 2n = 33$, giving $n = 5$. To verify: $5$ notebooks cost $\\$15$ and $9$ pens cost $\\$18$, totaling $\\$33$ for $14$ items.', NULL, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


