-- Q20: Math MCQ Easy — Advanced Math / Equivalent Expressions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM20FICUM', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq',
  E'Which of the following is equivalent to $3x(2x + 4) - 6x$?',
  NULL,
  '[{"key":"A","text":"$6x^2 + 6x$"},{"key":"B","text":"$6x^2 + 12x$"},{"key":"C","text":"$6x^2 - 6x$"},{"key":"D","text":"$6x^2 + 18x$"}]'::jsonb,
  'A', NULL,
  E'The correct answer is A. Distribute $3x$ across the binomial: $3x(2x + 4) = 6x^2 + 12x$. Then subtract $6x$: $6x^2 + 12x - 6x = 6x^2 + 6x$. Choice B neglects the subtraction of $6x$. Choice C incorrectly subtracts $12x$ instead of $6x$ from the distributed result.',
  '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb,
  NULL, 'draft', 1, 45, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q21: Math MCQ Medium — Advanced Math / Equivalent Expressions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM291NZ8Z', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq',
  E'Which of the following is equivalent to $2x^2 + 7x - 15$?',
  NULL,
  '[{"key":"A","text":"$(2x - 3)(x + 5)$"},{"key":"B","text":"$(2x + 3)(x - 5)$"},{"key":"C","text":"$(2x - 5)(x + 3)$"},{"key":"D","text":"$(2x + 5)(x - 3)$"}]'::jsonb,
  'A', NULL,
  E'The correct answer is A. To factor $2x^2 + 7x - 15$, find two numbers that multiply to $2 \\times (-15) = -30$ and add to $7$. Those numbers are $10$ and $-3$. Rewrite the middle term: $2x^2 + 10x - 3x - 15 = 2x(x + 5) - 3(x + 5) = (2x - 3)(x + 5)$. Choice B expands to $2x^2 - 7x - 15$, which has the wrong sign on the linear term. Choice D expands to $2x^2 - x - 15$.',
  '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb,
  NULL, 'draft', 1, 75, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q22: Math MCQ Medium — Advanced Math / Equivalent Expressions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM27PC49J', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq',
  E'Which of the following is equivalent to $(3x + 2)^2 - (x - 2)^2$?',
  NULL,
  '[{"key":"A","text":"$8x(x + 1)$"},{"key":"B","text":"$8x(x + 2)$"},{"key":"C","text":"$4x(2x + 1)$"},{"key":"D","text":"$10x^2 + 8$"}]'::jsonb,
  'B', NULL,
  E'The correct answer is B. Apply the difference of squares identity $a^2 - b^2 = (a - b)(a + b)$ with $a = 3x + 2$ and $b = x - 2$. Then $a - b = 3x + 2 - (x - 2) = 2x + 4$ and $a + b = 3x + 2 + x - 2 = 4x$. The product is $(2x + 4)(4x) = 4x(2x + 4) = 8x(x + 2)$, which equals $8x^2 + 16x$. Choice A results from incorrectly computing $a - b = 2x + 2$ by dropping the sign change on $-2$. Choice D comes from expanding each square separately and combining terms incorrectly.',
  '{"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb,
  NULL, 'draft', 1, 75, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q23: Math MCQ Hard — Advanced Math / Equivalent Expressions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM2NCLD97', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq',
  E'Which of the following is the completely factored form of $x^4 - 13x^2 + 36$?',
  NULL,
  '[{"key":"A","text":"$(x^2 - 3)(x^2 - 12)$"},{"key":"B","text":"$(x - 2)(x + 2)(x - 3)(x + 3)$"},{"key":"C","text":"$(x^2 - 6)^2$"},{"key":"D","text":"$(x - 2)^2(x - 3)^2$"}]'::jsonb,
  'B', NULL,
  E'The correct answer is B. Substitute $u = x^2$ to rewrite the expression as $u^2 - 13u + 36$. Factor this quadratic: find two numbers that multiply to $36$ and add to $-13$, which are $-4$ and $-9$. So $u^2 - 13u + 36 = (u - 4)(u - 9) = (x^2 - 4)(x^2 - 9)$. Apply the difference of squares to each factor: $x^2 - 4 = (x - 2)(x + 2)$ and $x^2 - 9 = (x - 3)(x + 3)$. The complete factorization is $(x - 2)(x + 2)(x - 3)(x + 3)$. Choice A uses incorrect factor pairs ($-3$ and $-12$ multiply to $36$ but sum to $-15$, not $-13$). Choice C squares $(x^2 - 6)$, which gives $x^4 - 12x^2 + 36$. Choice D omits the sum factors and would expand to $(x^2 - 5x + 6)^2$.',
  '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb,
  NULL, 'draft', 1, 105, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q24: Math MCQ Easy — Advanced Math / Nonlinear Equations in One Variable and Systems of Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
