-- Q26: Math MCQ Hard — Advanced Math / Nonlinear Equations in One Variable and Systems of Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM2GP6ACX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq',
  E'The system of equations below has exactly one solution $(x, y)$.\n\n$$y = x + 1$$\n$$y = x^2 - 3x + 5$$\n\nWhat is the value of $x + y$?',
  NULL,
  '[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]'::jsonb,
  'C', NULL,
  E'The correct answer is C. Substitute $y = x + 1$ into the second equation: $x + 1 = x^2 - 3x + 5$. Rearranging gives $x^2 - 4x + 4 = 0$, which factors as $(x - 2)^2 = 0$. So $x = 2$ and $y = 2 + 1 = 3$. Therefore $x + y = 2 + 3 = 5$. Choice A gives only the $y$-value. Choice B results from an arithmetic error when combining like terms. Choice D comes from incorrectly solving $x^2 - 4x + 4 = 0$ as having roots $x = 1$ and $x = 4$.',
  '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb,
  NULL, 'draft', 1, 105, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q27: Math MCQ Hard — Advanced Math / Nonlinear Equations in One Variable and Systems of Equations in Two Variables
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM2RYD267', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq',
  E'For what positive value of $k$ does the equation $x^2 + kx + 9 = 0$ have exactly one real solution?',
  NULL,
  '[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$9$"},{"key":"D","text":"$18$"}]'::jsonb,
  'B', NULL,
  E'The correct answer is B. A quadratic equation $ax^2 + bx + c = 0$ has exactly one real solution when the discriminant equals zero: $b^2 - 4ac = 0$. Here $a = 1$, $b = k$, and $c = 9$, so $k^2 - 4(1)(9) = 0$, which gives $k^2 = 36$. Since $k$ must be positive, $k = 6$. Choice A confuses the square root of $9$ with the required discriminant condition. Choice C uses the value of $c$ directly. Choice D results from computing $2 \\times 9 = 18$ instead of using the discriminant formula correctly.',
  '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb,
  NULL, 'draft', 1, 105, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

