-- Q29: Math MCQ Medium — Advanced Math / Nonlinear Functions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM27SV61Z', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq',
  E'The function $f$ is defined by $f(x) = 2(x - 1)^2 + 5$. The function $g$ is defined by $g(x) = f(x - 3)$. What is the vertex of the graph of $g$?',
  NULL,
  '[{"key":"A","text":"$(4, 5)$"},{"key":"B","text":"$(-2, 5)$"},{"key":"C","text":"$(1, 8)$"},{"key":"D","text":"$(4, 8)$"}]'::jsonb,
  'A', NULL,
  E'The correct answer is A. Since $g(x) = f(x - 3)$, the graph of $g$ is the graph of $f$ shifted $3$ units to the right. The vertex of $f$ is $(1, 5)$, so shifting right by $3$ gives the vertex $(1 + 3, 5) = (4, 5)$. Alternatively, $g(x) = 2((x - 3) - 1)^2 + 5 = 2(x - 4)^2 + 5$, confirming the vertex is $(4, 5)$. Choice B shifts left instead of right. Choice C shifts the $y$-coordinate instead of the $x$-coordinate.',
  '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb,
  NULL, 'draft', 1, 75, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);

-- Q30: Math Grid-in Hard — Advanced Math / Nonlinear Functions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution)
VALUES (
  'SATM2HH9EFF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in',
  E'How many distinct real zeros does the function $f(x) = x^3 - 6x^2 + 11x - 6$ have?',
  NULL,
  '[]'::jsonb,
  '3', ARRAY['3'],
  E'The correct answer is 3. Test $x = 1$: $f(1) = 1 - 6 + 11 - 6 = 0$, so $(x - 1)$ is a factor. Perform polynomial division: $x^3 - 6x^2 + 11x - 6 = (x - 1)(x^2 - 5x + 6)$. Factor the quadratic: $x^2 - 5x + 6 = (x - 2)(x - 3)$. Therefore $f(x) = (x - 1)(x - 2)(x - 3)$, which has three distinct real zeros at $x = 1$, $x = 2$, and $x = 3$. Each zero has multiplicity one, confirming there are exactly $3$ distinct real zeros.',
  NULL,
  NULL, 'draft', 1, 120, false,
  '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb,
  '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb
);


