-- Q31: Math MCQ Easy — Problem Solving and Data Analysis / Ratios, Rates, Proportional Relationships, and Units
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TGFZI1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe requires $3$ cups of flour to make $24$ cookies. At this rate, how many cups of flour are needed to make $60$ cookies?', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$7.5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Set up a proportion: $\\frac{3}{24} = \\frac{x}{60}$. Cross-multiplying gives $24x = 180$, so $x = 7.5$. Therefore, $7.5$ cups of flour are needed. Option A results from dividing $60$ by $12$ incorrectly. Option C comes from rounding $7.5$ up. Option D results from an incorrect ratio setup.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q32: Math MCQ Medium — Problem Solving and Data Analysis / Percentages
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23SJ0OJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store marks up the wholesale price of an item by $40\\%$ and then offers a $25\\%$ discount on the marked-up price during a sale. If the wholesale price of the item is $\\$50$, what is the sale price?', NULL, '[{"key":"A","text":"$\\$50.00$"},{"key":"B","text":"$\\$52.50$"},{"key":"C","text":"$\\$55.00$"},{"key":"D","text":"$\\$57.50$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The marked-up price is $50 \\times 1.40 = \\$70$. The $25\\%$ discount reduces this to $70 \\times 0.75 = \\$52.50$. A common error is to assume the $40\\%$ markup and $25\\%$ discount cancel to a $15\\%$ markup (Option D, $\\$57.50$), but percentages apply to different bases. Option A incorrectly assumes the markup and discount fully cancel. Option C results from applying $\\frac{40-25}{2}$ as a $10\\%$ net change.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q33: Math MCQ Medium — Problem Solving and Data Analysis / One-Variable Data: Distributions and Measures of Center and Spread
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XPLYJC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A teacher recorded the following quiz scores for $7$ students: $12, 15, 15, 18, 20, 22, 25$. What is the median score?', NULL, '[{"key":"A","text":"$15$"},{"key":"B","text":"$18$"},{"key":"C","text":"$18.14$"},{"key":"D","text":"$20$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The data set has $7$ values, which are already in ascending order. The median is the middle value, which is the $4$th value: $18$. Option A is the mode (most frequent value), not the median. Option C is approximately the mean ($\\frac{127}{7} \\approx 18.14$), which is a different measure of center. Option D is the $5$th value, resulting from a counting error.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q34: Math Grid-in Hard — Problem Solving and Data Analysis / Two-Variable Data: Models and Scatterplots
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGJV1P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collected data on the number of hours spent studying and the corresponding test scores for a group of students. The line of best fit for the data is modeled by $y = 2.4x + 3.2$, where $x$ is the number of hours studied and $y$ is the predicted test score. According to this model, what is the predicted test score, rounded to the nearest whole number, for a student who studies for $15$ hours?', NULL, '[]'::jsonb, '39', ARRAY['39'], E'The correct answer is $39$. Substituting $x = 15$ into the equation: $y = 2.4(15) + 3.2 = 36 + 3.2 = 39.2$. Rounded to the nearest whole number, the predicted score is $39$. A common error is to round $39.2$ up to $40$, but standard rounding rules require rounding down since the decimal part is less than $0.5$.', NULL, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q35: Math MCQ Hard — Problem Solving and Data Analysis / Probability and Conditional Probability
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM282PA7B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of $80$ high school students recorded whether each student plays a sport and whether the student has a grade point average (GPA) of $3.5$ or above. Of the $40$ students who play a sport, $18$ have a GPA of $3.5$ or above. Of the $40$ students who do not play a sport, $12$ have a GPA of $3.5$ or above. If a student is selected at random from those who play a sport, what is the probability that the student has a GPA of $3.5$ or above?', NULL, '[{"key":"A","text":"$\\dfrac{9}{40}$"},{"key":"B","text":"$\\dfrac{9}{20}$"},{"key":"C","text":"$\\dfrac{3}{8}$"},{"key":"D","text":"$\\dfrac{3}{5}$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The conditional probability is $P(\\text{GPA} \\geq 3.5 \\mid \\text{plays sport}) = \\frac{18}{40} = \\frac{9}{20}$. Option A ($\\frac{9}{40}$) results from dividing $18$ by the total $80$ instead of the $40$ who play a sport, confusing joint probability with conditional probability. Option C ($\\frac{3}{8} = \\frac{30}{80}$) adds the two GPA groups ($18 + 12 = 30$) and divides by the total, finding $P(\\text{GPA} \\geq 3.5)$ overall rather than the conditional probability. Option D uses an incorrect numerator.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


