-- Q36: Math MCQ Medium — Geometry and Trigonometry / Lines, Angles, and Triangles
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B2Q9TL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of the exterior angle at vertex $R$ is $130°$. If the measure of angle $P$ is $55°$, what is the measure, in degrees, of angle $Q$?', NULL, '[{"key":"A","text":"$50$"},{"key":"B","text":"$55$"},{"key":"C","text":"$75$"},{"key":"D","text":"$130$"}]'::jsonb, 'C', NULL, E'The correct answer is C. By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore, $\\angle P + \\angle Q = 130°$, which gives $55° + \\angle Q = 130°$, so $\\angle Q = 75°$. Option A ($50°$) comes from subtracting $130° - 80°$ due to an arithmetic error. Option B ($55°$) assumes $\\angle Q = \\angle P$. Option D ($130°$) confuses the exterior angle with the interior angle at $R$.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q37: Math MCQ Hard — Geometry and Trigonometry / Right Triangles and Trigonometry
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DMQ2BO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands $50$ feet from the base of a building and measures the angle of elevation to the top of the building to be $62°$. Which of the following is closest to the height of the building, in feet?', NULL, '[{"key":"A","text":"$27$"},{"key":"B","text":"$56$"},{"key":"C","text":"$94$"},{"key":"D","text":"$107$"}]'::jsonb, 'C', NULL, E'The correct answer is C. In the right triangle formed, the height $h$ is opposite the $62°$ angle and the $50$-foot distance is adjacent. Using $\\tan(62°) = \\frac{h}{50}$, we get $h = 50 \\tan(62°) \\approx 50(1.8807) \\approx 94$. Option A ($27$) results from using $\\sin(62°)$ divided by $50$ instead of multiplied. Option B ($56$) comes from incorrectly using $50 \\times \\sin(62°) \\approx 44.1$ and rounding erroneously, or from $50 \\times \\tan(48°)$. Option D ($107$) results from using $\\frac{50}{\\tan(25°)}$ or a similar reciprocal error.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q38: Math Grid-in Medium — Geometry and Trigonometry / Circles
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KP8TM5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $(x - 3)^2 + (y + 2)^2 = 49$. What is the diameter of the circle?', NULL, '[]'::jsonb, '14', ARRAY['14'], E'The correct answer is $14$. The equation $(x - 3)^2 + (y + 2)^2 = 49$ is in standard form $(x - h)^2 + (y - k)^2 = r^2$, where $r^2 = 49$. Therefore $r = 7$, and the diameter is $2r = 14$. A common error is to give the radius ($7$) instead of the diameter, or to confuse $r^2 = 49$ with $r = 49$.', NULL, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q39: Math MCQ Easy — Geometry and Trigonometry / Area and Volume
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VN4FUA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $12$ feet and a width of $8$ feet. What is the area of the garden, in square feet?', NULL, '[{"key":"A","text":"$20$"},{"key":"B","text":"$40$"},{"key":"C","text":"$80$"},{"key":"D","text":"$96$"}]'::jsonb, 'D', NULL, E'The correct answer is D. The area of a rectangle is $A = l \\times w = 12 \\times 8 = 96$ square feet. Option A ($20$) is the sum $12 + 8$, confusing addition with multiplication. Option B ($40$) is the perimeter $2(12 + 8) = 40$, not the area. Option C ($80$) results from an arithmetic error such as $12 \\times 8 = 80$.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q40: Math Grid-in Hard — Geometry and Trigonometry / Area and Volume
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IB71OV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A solid is formed by placing a smaller rectangular prism on top of a larger rectangular prism. The larger prism has a length of $8$ inches, a width of $8$ inches, and a height of $3$ inches. The smaller prism, centered on top, has a length of $4$ inches, a width of $4$ inches, and a height of $6$ inches. What is the total volume of the solid, in cubic inches?', NULL, '[]'::jsonb, '288', ARRAY['288'], E'The correct answer is $288$. The volume of the larger prism is $8 \\times 8 \\times 3 = 192$ cubic inches. The volume of the smaller prism is $4 \\times 4 \\times 6 = 96$ cubic inches. The total volume is $192 + 96 = 288$ cubic inches. A common error is to compute the volume of a single prism with combined dimensions, such as $8 \\times 8 \\times 9 = 576$, which treats the solid as one rectangular prism. Another error is to subtract the smaller volume from the larger, yielding $192 - 96 = 96$.', NULL, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


