-- Q41: RW MCQ Easy — Craft and Structure / Words in Context
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QIVG38', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does "volume" most nearly mean?', E'Marine biologists studying coral reefs in the Pacific have noted that the sheer volume of plastic debris washing ashore has increased dramatically over the past decade. Where researchers once collected a few dozen fragments per survey, they now routinely gather hundreds, overwhelming the capacity of local recycling programs.', '[{"key":"A","text":"loudness of sound"},{"key":"B","text":"single book in a series"},{"key":"C","text":"amount or quantity"},{"key":"D","text":"control knob on a device"}]'::jsonb, 'C', NULL, E'The correct answer is C. In this passage, "volume" refers to the amount of plastic debris, as indicated by the contrast between "a few dozen fragments" and "hundreds." The word describes a quantity that has increased, not sound (A), a book (B), or a physical knob (D).', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q42: RW MCQ Easy — Craft and Structure / Words in Context
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW279ORZ6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does "drawn" most nearly mean?', E'The young novelist had always been drawn to stories about unlikely friendships. Her earliest memories involved sitting beside her grandmother, listening to tales of a wandering musician who befriended a reclusive shepherd in the hills of Andalusia. These stories shaped her conviction that connection could bridge any divide.', '[{"key":"A","text":"sketched with a pencil"},{"key":"B","text":"attracted or pulled toward"},{"key":"C","text":"removed from a container"},{"key":"D","text":"stretched or elongated"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage describes the novelist''s longstanding interest in stories about unlikely friendships, indicating that "drawn" means attracted or pulled toward. The context of emotional inclination rules out sketching (A), extracting (C), or stretching (D).', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q43: RW MCQ Medium — Craft and Structure / Words in Context
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GALDOA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does "currency" most nearly mean?', E'Among historians of medieval trade, the idea that long-distance commerce was rare before the twelfth century has lost much of its currency. Recent archaeological finds along inland river routes—glazed pottery from distant kilns, standardized glass weights, even fragments of silk—suggest that merchant networks were far more extensive than earlier scholars acknowledged.', '[{"key":"A","text":"system of money used in a country"},{"key":"B","text":"prevalence or acceptance"},{"key":"C","text":"rate of exchange between nations"},{"key":"D","text":"physical coins and banknotes"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage states that the idea has "lost much of its currency," meaning the idea is no longer widely accepted or prevalent among historians. The archaeological evidence has undermined the old view. While "currency" often refers to money (A, D) or exchange rates (C), the context here concerns the acceptance of a scholarly idea, not financial instruments.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q44: RW MCQ Hard — Craft and Structure / Words in Context
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XR6EOS', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does "plastic" most nearly mean?', E'The choreographer spoke of the dancer''s body as a plastic medium, one that could be molded and reshaped in rehearsal to convey grief as convincingly as exuberance. Unlike a painted canvas, which fixes an image permanently, the human form offers the artist a living material whose expressive range is continually renewed with each performance.', '[{"key":"A","text":"synthetic or artificial"},{"key":"B","text":"related to credit cards"},{"key":"C","text":"capable of being shaped or molded"},{"key":"D","text":"superficial or insincere"}]'::jsonb, 'C', NULL, E'The correct answer is C. The choreographer describes the dancer''s body as something that "could be molded and reshaped," directly defining "plastic" as capable of being shaped. The passage contrasts this malleability with the fixedness of a painted canvas, reinforcing the idea of physical adaptability. The word does not refer to synthetic material (A), financial instruments (B), or insincerity (D). Option D is a particularly tempting distractor because "plastic" can colloquially suggest artificiality, but the context here emphasizes genuine artistic flexibility.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q45: RW MCQ Easy — Craft and Structure / Text Structure and Purpose
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T7TQ3V', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text?', E'Every autumn, monarch butterflies undertake one of the most remarkable migrations in the animal kingdom. Traveling up to three thousand miles from southern Canada to the mountain forests of central Mexico, the butterflies navigate using a combination of the sun''s position and Earth''s magnetic field. They arrive at the same small clusters of oyamel fir trees that their great-grandparents occupied the previous year.', '[{"key":"A","text":"It argues that monarch butterflies should receive greater legal protection."},{"key":"B","text":"It describes a natural phenomenon and explains how it occurs."},{"key":"C","text":"It compares monarch migration patterns with those of other insect species."},{"key":"D","text":"It challenges a common misconception about butterfly behavior."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage describes the monarch butterfly migration and explains the navigational mechanisms the butterflies use. It does not advocate for legal protection (A), compare species (C), or challenge a misconception (D).', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q46: RW MCQ Medium — Craft and Structure / Text Structure and Purpose
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S4886O', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Some economists argue that universal basic income would reduce poverty without discouraging employment, pointing to pilot programs in Finland and Stockton, California, where recipients maintained or even increased their working hours. Other economists counter that such programs, when scaled nationally, would require tax increases large enough to slow economic growth. They note that pilot programs, which are temporary and limited in scope, cannot reliably predict the behavioral effects of a permanent, nationwide policy.', '[{"key":"A","text":"It presents a proposal, then provides evidence that the proposal has already been implemented successfully."},{"key":"B","text":"It introduces a claim supported by evidence, then presents a counterargument that questions the evidence''s applicability."},{"key":"C","text":"It describes a problem, then evaluates two equally flawed solutions to that problem."},{"key":"D","text":"It summarizes a historical debate, then explains why the debate has been resolved."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage first presents the claim that universal basic income reduces poverty without discouraging work, citing pilot programs as evidence. It then introduces a counterargument that challenges whether those pilot programs can predict outcomes at a national scale. The text does not claim successful implementation (A), describe two flawed solutions (C), or suggest the debate is resolved (D).', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q47: RW MCQ Medium — Craft and Structure / Text Structure and Purpose
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVE7RW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the purpose of the text?', E'The cellist drew the bow across the lowest string, and the note swelled until it seemed to press against the walls of the auditorium. Elena closed her eyes. She had not expected the music to feel so physical—less like sound and more like a hand placed flat against her sternum. When the phrase ended, the silence that followed was not empty but dense, as though the air itself had been rearranged.', '[{"key":"A","text":"To convey a character''s intense sensory experience of a musical performance"},{"key":"B","text":"To provide technical details about how a cello produces sound"},{"key":"C","text":"To argue that live music is superior to recorded music"},{"key":"D","text":"To introduce a conflict between two characters at a concert"}]'::jsonb, 'A', NULL, E'The correct answer is A. The passage focuses on Elena''s physical and emotional response to the cello performance, using sensory language such as "a hand placed flat against her sternum" and describing the silence as "dense." The text does not explain cello acoustics (B), argue for live music''s superiority (C), or introduce a conflict (D).', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q48: RW MCQ Hard — Craft and Structure / Text Structure and Purpose
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W96W8Z', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the text?', E'It would be convenient to claim that the decline of handwritten correspondence began with the telegraph, accelerated with the telephone, and reached its conclusion with email. Convenient, but misleading. Each new technology did reduce the frequency of personal letters, yet none eliminated the particular quality that a handwritten note conveys: the evidence of time deliberately spent. A typed message communicates content; a handwritten one communicates content and commitment. The distinction matters less for efficiency than for trust—recipients interpret the visible effort of handwriting as a signal that the sender''s words carry personal weight.', '[{"key":"A","text":"It traces the complete history of written communication from ancient times to the present."},{"key":"B","text":"It refutes a seemingly logical narrative in order to highlight a quality that technology has not replicated."},{"key":"C","text":"It contrasts two specific technologies to determine which one is more effective for communication."},{"key":"D","text":"It defends the continued use of handwritten letters by dismissing the value of digital communication."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage opens by presenting a tidy narrative about handwriting''s decline ("It would be convenient to claim..."), then immediately labels it "misleading." The rest of the text identifies what handwriting uniquely conveys—deliberate effort as a trust signal—which no communication technology has replicated. This structure is one of refuting a convenient narrative to illuminate a persisting quality. Option A is wrong because the passage does not trace ancient history. Option C is wrong because the text discusses multiple technologies without declaring one superior. Option D overstates the argument: the author does not dismiss digital communication but rather identifies a specific quality it lacks.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q49: RW MCQ Medium — Craft and Structure / Cross-Text Connections
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GOBQ5W', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1\nUrban green spaces provide measurable mental health benefits. A 2024 study of over four thousand city residents found that those living within a ten-minute walk of a park reported significantly lower levels of chronic stress and higher life satisfaction scores than those without nearby green space, even after controlling for income and education.\n\nText 2\nWhile parks undeniably improve quality of life, their placement is rarely equitable. In many cities, the neighborhoods that would benefit most from green space—those with high population density, elevated pollution levels, and limited recreational infrastructure—are precisely the ones least likely to receive new parks, because land acquisition costs there are prohibitively high.', '[{"key":"A","text":"By agreeing that green spaces improve mental health but noting that access to those spaces is unevenly distributed"},{"key":"B","text":"By arguing that the study cited in Text 1 used a flawed methodology and cannot be trusted"},{"key":"C","text":"By suggesting that mental health benefits are less important than the economic benefits of parks"},{"key":"D","text":"By claiming that urban residents do not actually want more green spaces in their neighborhoods"}]'::jsonb, 'A', NULL, E'The correct answer is A. Text 2 opens by conceding that "parks undeniably improve quality of life," which aligns with Text 1''s claim. However, Text 2''s central point is that park placement is inequitable, meaning the benefits Text 1 describes are not equally accessible. Text 2 does not question the study''s methodology (B), prioritize economic benefits (C), or claim residents oppose green spaces (D).', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q50: RW MCQ Medium — Craft and Structure / Cross-Text Connections
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AHB5OL', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1\nThe preservation of endangered languages is often framed as a cultural imperative, but it is also a scientific one. Each language encodes unique observations about local ecosystems—plant classifications, seasonal patterns, animal behaviors—that may have no equivalent in dominant languages. When a language disappears, this ecological knowledge frequently disappears with it.\n\nText 2\nLanguage preservation efforts, however well-intentioned, must contend with a practical reality: speakers of endangered languages often choose to raise their children in a dominant language because fluency in that language offers greater access to education, employment, and social mobility. Preservation programs that ignore these economic incentives risk placing an unfair burden on the very communities they aim to help.', '[{"key":"A","text":"Text 1 presents a justification for language preservation, while Text 2 identifies a tension that complicates preservation efforts."},{"key":"B","text":"Text 1 and Text 2 both argue that endangered languages should not be preserved."},{"key":"C","text":"Text 1 describes the history of language extinction, while Text 2 proposes a specific solution."},{"key":"D","text":"Text 1 challenges a scientific claim, while Text 2 supports that same claim with additional evidence."}]'::jsonb, 'A', NULL, E'The correct answer is A. Text 1 argues that language preservation is important because languages encode irreplaceable ecological knowledge. Text 2 does not reject preservation but highlights a complication: speakers often shift to dominant languages for economic reasons, creating tension for preservation programs. Text 2 does not oppose preservation outright (B), propose a specific solution (C), or support a claim that Text 1 challenges (D).', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q51: RW MCQ Hard — Craft and Structure / Cross-Text Connections
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XEAV03', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1\nThe most reliable archaeological interpretations are those constrained by material evidence. When researchers reconstruct the social hierarchies of ancient settlements, they should rely on verifiable indicators—burial goods, architectural differentiation, caloric evidence from refuse deposits—rather than on analogies drawn from modern societies. Contemporary social structures are products of historical contingencies that have no necessary parallel in the ancient world, and importing them risks projecting our assumptions onto cultures that operated under fundamentally different conditions.\n\nText 2\nEthnoarchaeologists working among the Hadza people of Tanzania have drawn parallels between Hadza food-sharing practices and the distribution patterns of animal bones found at Olduvai Gorge sites dating to 1.8 million years ago. By observing how a living community processes and distributes resources, these researchers argue, we gain interpretive frameworks that pure artifact analysis cannot provide. The behavioral context supplied by ethnographic analogy transforms otherwise ambiguous scatter patterns into evidence of cooperative social organization.', '[{"key":"A","text":"As a productive method that strengthens archaeological conclusions by grounding them in observed human behavior"},{"key":"B","text":"As a well-intentioned but methodologically risky practice that may impose modern social patterns onto ancient contexts"},{"key":"C","text":"As an outdated technique that most contemporary archaeologists have already abandoned"},{"key":"D","text":"As a valuable approach when applied to recent historical periods but inappropriate for prehistoric sites"}]'::jsonb, 'B', NULL, E'The correct answer is B. Text 1 explicitly warns against using analogies from modern societies to interpret ancient ones, arguing that contemporary structures are "products of historical contingencies" with "no necessary parallel in the ancient world." Text 2 describes precisely this kind of ethnographic analogy—using observations of a living community to interpret million-year-old sites. The author of Text 1 would likely view this as methodologically risky because it may project modern assumptions onto ancient cultures. However, nothing in Text 1 suggests the approach is entirely worthless or ill-intentioned, making "well-intentioned but methodologically risky" the most precise characterization. Option A contradicts Text 1''s core argument. Option C overstates the case, as Text 1 does not claim the method is abandoned. Option D introduces a time-period distinction that Text 1 does not make.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


-- ═══════════════════════════════════════════════════════════
-- RW — Information and Ideas (10 questions)
