-- Q52: RW MCQ Easy — Information and Ideas / Central Ideas and Details
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TL9IDQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', 'Which choice best states the main idea of the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly twenty-five percent of all marine species. Marine biologists attribute this remarkable productivity to the symbiotic relationship between coral polyps and tiny algae called zooxanthellae. The algae live within the coral''s tissue, converting sunlight into nutrients that feed the coral, while the coral provides the algae with shelter and the compounds they need for photosynthesis. When ocean temperatures rise even slightly, this partnership breaks down: the coral expels the algae, loses its color, and often dies—a process known as coral bleaching.', '[{"key":"A","text":"Coral reefs are the largest structures built by living organisms on Earth."},{"key":"B","text":"Coral reefs support a disproportionate share of marine life due to a symbiotic relationship that is vulnerable to temperature changes."},{"key":"C","text":"Scientists have recently discovered why coral reefs lose their color during periods of warm weather."},{"key":"D","text":"Zooxanthellae are essential to ocean ecosystems because they perform photosynthesis more efficiently than other marine algae."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage explains that coral reefs support a vast number of species relative to their small size, attributes this to the symbiosis between corals and zooxanthellae, and notes that rising temperatures disrupt this relationship. Option A introduces an unsupported claim about reef structures. Option C mischaracterizes the discovery as recent. Option D overstates the role of zooxanthellae beyond what the passage describes.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q53: RW MCQ Medium — Information and Ideas / Central Ideas and Details
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28A1VSQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', 'Which choice best states the main idea of the text?', E'In the 1960s, psychologist Walter Mischel conducted a series of experiments in which young children were offered a choice between one small reward immediately or two rewards if they waited for a period of time. Follow-up studies decades later suggested that children who had waited longer tended to have better life outcomes, including higher test scores and lower rates of substance abuse. However, a 2018 replication study by Tyler Watts and colleagues found that once researchers controlled for socioeconomic background, the correlation between waiting time and later outcomes largely disappeared. The findings prompted debate about whether the original results reflected self-control or simply the advantages associated with growing up in wealthier households.', '[{"key":"A","text":"Recent research has conclusively disproven the idea that self-control in childhood predicts success in adulthood."},{"key":"B","text":"A well-known study linking childhood self-control to later success has been challenged by research suggesting socioeconomic factors may better explain the original findings."},{"key":"C","text":"Walter Mischel''s experiments demonstrated that children from wealthy families are better at delaying gratification than children from lower-income families."},{"key":"D","text":"Psychologists now agree that self-control is entirely determined by a child''s economic circumstances rather than by individual temperament."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage describes Mischel''s original findings, then presents a replication study that challenged those findings by showing socioeconomic background accounted for much of the observed correlation. The passage frames this as a debate, not a settled conclusion. Option A overstates the replication study''s impact by saying it "conclusively disproven" the idea. Option C attributes a claim to Mischel that the passage does not make. Option D presents a consensus that the passage does not support.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q54: RW MCQ Medium — Information and Ideas / Central Ideas and Details
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O44RO5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', 'According to the text, what is one reason the Voyager probes have continued to provide useful data long after their primary missions ended?', E'Launched in 1977, NASA''s Voyager 1 and Voyager 2 spacecraft were designed to study Jupiter and Saturn during flybys expected to last about four years. Yet both probes remain operational decades later, transmitting data from the outermost regions of the solar system. Scientists credit the probes'' longevity partly to their radioisotope thermoelectric generators, which convert heat from decaying plutonium-238 into electricity without moving parts that could wear out. Although the power output diminishes by roughly four watts per year, mission engineers have compensated by selectively shutting down nonessential instruments, allowing the most critical sensors to continue functioning.', '[{"key":"A","text":"Their solar panels were engineered to absorb energy even at great distances from the Sun."},{"key":"B","text":"They carry power sources that generate electricity from radioactive decay and have no moving components susceptible to mechanical failure."},{"key":"C","text":"NASA periodically uploads software patches that improve the efficiency of the probes'' onboard computers."},{"key":"D","text":"The probes were originally built with redundant copies of every scientific instrument."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage explicitly states that the probes'' radioisotope thermoelectric generators convert heat from decaying plutonium-238 into electricity "without moving parts that could wear out," directly supporting option B. Option A is incorrect because the passage describes nuclear generators, not solar panels. Options C and D introduce details not mentioned in the passage.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q55: RW MCQ Hard — Information and Ideas / Central Ideas and Details
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21UQ99Z', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', 'Which choice best states the main idea of the text?', E'Literary scholars have long debated whether the rise of the novel in eighteenth-century England was driven primarily by changes in readership or by innovations in narrative form. Ian Watt''s influential 1957 study argued that the novel emerged because a growing middle class demanded realistic portrayals of everyday life. More recent critics, however, have complicated this account. Michael McKeon contends that the novel arose from an epistemological crisis—a broad cultural uncertainty about how truth claims could be verified—that made fictional narrative a vehicle for exploring competing standards of evidence. Neither view fully accounts for the genre''s development, but McKeon''s framework has the advantage of explaining why early novels so often dramatize conflicts between personal testimony, documentary proof, and social reputation.', '[{"key":"A","text":"Ian Watt''s theory about the rise of the English novel has been entirely replaced by Michael McKeon''s epistemological framework."},{"key":"B","text":"The English novel developed primarily because middle-class readers wanted fiction that depicted their own social experiences."},{"key":"C","text":"Scholars continue to debate the origins of the English novel, with a more recent theory offering a broader explanation rooted in cultural questions about how truth is established."},{"key":"D","text":"Early English novels are best understood as philosophical arguments disguised as fiction rather than as works of literary art."}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage presents two scholarly positions on the rise of the novel—Watt''s readership-driven account and McKeon''s epistemological-crisis account—and notes that neither fully explains the genre''s development while acknowledging McKeon''s broader explanatory power. Option A overstates the case by claiming Watt''s theory has been "entirely replaced." Option B captures only Watt''s position and ignores the passage''s emphasis on the debate and McKeon''s contribution. Option D makes an interpretive leap the passage does not support, reducing novels to "philosophical arguments."', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q56: RW MCQ Easy — Information and Ideas / Command of Evidence
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XDGDN2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', 'Which finding, if true, would most directly support the researchers'' conclusion?', E'A team of agricultural scientists studied tomato plants grown under different light conditions. One group was exposed to supplemental blue LED light for four hours each evening, while a control group received only natural sunlight. After eight weeks, the researchers concluded that supplemental blue light increases the concentration of lycopene, the pigment responsible for the red color of ripe tomatoes.', '[{"key":"A","text":"Tomato plants exposed to blue LED light grew taller on average than plants in the control group."},{"key":"B","text":"The blue-light group produced tomatoes with thirty percent higher lycopene levels than the control group."},{"key":"C","text":"Farmers who use greenhouses generally report higher crop yields than those who grow tomatoes outdoors."},{"key":"D","text":"Lycopene is an antioxidant that has been linked to various health benefits in nutritional studies."}]'::jsonb, 'B', NULL, E'The correct answer is B. The researchers'' conclusion is specifically that supplemental blue light increases lycopene concentration. A finding that the blue-light group had thirty percent higher lycopene levels directly supports this claim. Option A addresses plant height, not lycopene. Option C discusses greenhouse yields generally and is not specific to the blue-light experiment. Option D provides background on lycopene''s health properties but does not address whether blue light increases its concentration.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q57: RW MCQ Medium — Information and Ideas / Command of Evidence
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27LSPRR', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', 'Which quotation from a researcher, if accurate, would best support the claim presented in the text?', E'Some economists argue that raising the minimum wage does not necessarily lead to significant job losses in the restaurant industry. They point out that restaurants can absorb higher labor costs through modest price increases, reduced employee turnover, and improved worker productivity. Critics counter that these adjustments have limits and that large wage hikes will eventually force employers to cut hours or positions.', '[{"key":"A","text":"\"Our analysis of fourteen cities that raised their minimum wage between 2015 and 2020 found no statistically significant decline in restaurant employment within two years of the increase.\""},{"key":"B","text":"\"Restaurants in states with higher minimum wages tend to have more experienced staff, which some owners attribute to the area''s cost of living rather than the wage floor itself.\""},{"key":"C","text":"\"When we surveyed restaurant owners, sixty-two percent said they would consider automating certain tasks if wages rose above fifteen dollars per hour.\""},{"key":"D","text":"\"The restaurant industry has historically had high turnover rates regardless of wage levels, making it difficult to isolate any single cause of staffing changes.\""}]'::jsonb, 'A', NULL, E'The correct answer is A. The claim in the text is that raising the minimum wage does not necessarily lead to significant job losses in the restaurant industry. Option A provides direct empirical evidence—data from fourteen cities showing no significant decline in restaurant employment—that supports this claim. Option B discusses staff experience but attributes it to cost of living, not the wage floor, making it tangential. Option C provides evidence that could support the critics'' counterargument about automation. Option D notes the difficulty of isolating causes, which neither supports nor refutes the specific claim.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q58: RW MCQ Hard — Information and Ideas / Command of Evidence
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23AXS7F', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', 'Which choice best describes evidence that would weaken the author''s argument?', E'Historian Elaine Chen has argued that the decline of handwritten correspondence in the late twentieth century fundamentally altered how people construct personal identity. In her view, the deliberate pace of letter writing encouraged sustained self-reflection: choosing words carefully, revisiting drafts, and committing thoughts to paper forced writers to synthesize their experiences into coherent narratives. Chen acknowledges that digital communication allows people to maintain contact with far more individuals simultaneously, but she maintains that the speed and brevity of emails and text messages discourage the kind of deep introspection that letters once fostered.', '[{"key":"A","text":"A study finding that people who regularly journal by hand report higher levels of self-awareness than those who do not keep journals."},{"key":"B","text":"Evidence that individuals who maintain long-running email correspondences with close friends engage in self-reflection at rates comparable to those documented among historical letter writers."},{"key":"C","text":"Research showing that the volume of personal correspondence has increased dramatically since the adoption of email and social media."},{"key":"D","text":"A survey indicating that most people under thirty have never sent a handwritten letter and prefer digital communication for its convenience."}]'::jsonb, 'B', NULL, E'The correct answer is B. Chen''s central argument is that digital communication discourages the deep introspection that letter writing fostered. Evidence showing that long-running email correspondences produce comparable levels of self-reflection would directly undermine this claim by demonstrating that digital formats can serve the same reflective function. Option A supports rather than weakens the argument by linking handwriting to self-awareness. Option C addresses volume of correspondence, not depth of reflection, and thus does not target Chen''s specific claim. Option D describes a generational preference but does not address whether digital communication actually limits introspection.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q59: RW MCQ Easy — Information and Ideas / Inferences
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NW8MRD', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', 'Based on the text, what can most reasonably be inferred about the Argentine ant?', E'The Argentine ant, native to South America, has established colonies on every continent except Antarctica. Unlike most ant species, Argentine ants from different colonies rarely fight one another, allowing them to form vast cooperative networks called supercolonies that can stretch for hundreds of miles. This cooperative behavior gives them a significant advantage over native ant species, which expend considerable energy defending their territories from neighboring colonies of the same species.', '[{"key":"A","text":"The Argentine ant is the only invasive insect species found on multiple continents."},{"key":"B","text":"The Argentine ant''s success as an invasive species is related to its ability to cooperate across colonies rather than compete with them."},{"key":"C","text":"Native ant species would be able to resist Argentine ant invasions if they formed larger colonies."},{"key":"D","text":"Argentine ants are unable to survive in cold climates, which explains their absence from Antarctica."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage explains that Argentine ants from different colonies rarely fight, forming supercolonies, and that this cooperation gives them an advantage over native species that waste energy on intra-species conflict. This directly supports the inference that their invasive success is linked to inter-colony cooperation. Option A makes a claim about other invasive insects that the passage does not address. Option C speculates about a solution the passage does not suggest. Option D introduces a climate-based explanation that the passage does not provide.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q60: RW MCQ Medium — Information and Ideas / Inferences
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AA0OW2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', 'Based on the text, what can most reasonably be inferred about the relationship between urban green spaces and residents'' mental health?', E'A 2022 study by researchers at the University of Exeter tracked the daily routines of 3,400 city residents across five European cities over eighteen months. Participants who lived within a five-minute walk of a park or community garden reported lower levels of stress and anxiety on standardized questionnaires than those who lived farther away. Importantly, the researchers found that the association held even after adjusting for income, employment status, and neighborhood safety—three factors often cited as confounding variables in earlier studies. However, the study relied on self-reported data and could not establish whether proximity to green space caused the observed differences or whether individuals with lower baseline anxiety were simply more likely to choose homes near parks.', '[{"key":"A","text":"Living near green spaces directly causes reductions in stress and anxiety among urban residents."},{"key":"B","text":"Previous studies on green spaces and mental health were fundamentally flawed because they failed to consider any confounding variables."},{"key":"C","text":"The observed association between green space proximity and lower stress levels is not easily explained by differences in income, employment, or neighborhood safety alone."},{"key":"D","text":"Self-reported questionnaires are unreliable tools for measuring mental health outcomes in large-scale studies."}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage states that the association between proximity to green space and lower stress held even after adjusting for income, employment status, and neighborhood safety. This supports the inference that these common confounding variables do not fully account for the observed pattern. Option A overstates the findings by asserting causation, which the passage explicitly says the study could not establish. Option B mischaracterizes earlier studies; the passage says those factors were "often cited," not that previous researchers ignored them entirely. Option D makes a broad claim about self-reported data that goes beyond the passage''s more limited caveat.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q61: RW MCQ Hard — Information and Ideas / Inferences
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MS4ZE4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', 'Based on the text, what can most reasonably be inferred about Kovalenko''s view of algorithmic curation?', E'In a 2024 essay, media theorist Daria Kovalenko challenges the common assumption that algorithmic content curation narrows users'' exposure to diverse viewpoints. She concedes that recommendation algorithms do create feedback loops, repeatedly surfacing content similar to what a user has previously engaged with. However, Kovalenko argues that this framing ignores a countervailing effect: before algorithmic curation, most people''s media consumption was constrained by geography, social class, and the editorial decisions of a small number of publishers. Algorithms, she contends, at least expose users to content produced outside their immediate social and geographic circles, even if that content is filtered through engagement-based ranking. Kovalenko stops short of calling algorithmic curation beneficial, instead describing it as a shift in the structure of informational constraint rather than an increase or decrease in diversity overall.', '[{"key":"A","text":"Kovalenko believes algorithmic curation produces a net increase in the diversity of viewpoints that users encounter."},{"key":"B","text":"Kovalenko regards algorithmic curation as replacing one set of limitations on information access with a different set, rather than simply reducing exposure to diverse perspectives."},{"key":"C","text":"Kovalenko argues that editorial gatekeeping by traditional publishers was more harmful to intellectual diversity than algorithmic filtering is."},{"key":"D","text":"Kovalenko considers the feedback loops created by recommendation algorithms to be a minor and largely overstated concern."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage states that Kovalenko describes algorithmic curation as "a shift in the structure of informational constraint rather than an increase or decrease in diversity overall," which directly aligns with the characterization of one set of limitations replacing another. Option A overstates her position; the passage explicitly says she "stops short of calling algorithmic curation beneficial." Option C implies a comparative judgment that Kovalenko does not make—she notes pre-algorithmic constraints but does not rank them as more harmful. Option D contradicts the passage, which states that she "concedes that recommendation algorithms do create feedback loops," indicating she takes them seriously rather than dismissing them.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


