-- Q62: RW MCQ Easy — Standard English Conventions / Boundaries
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D74MIJ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologists at the Coral Reef Research Institute have documented a sharp decline in staghorn coral populations along the Florida coastline ______ rising ocean temperatures and increased acidification are believed to be the primary factors driving this loss.', '[{"key":"A","text":"coastline, rising"},{"key":"B","text":"coastline. Rising"},{"key":"C","text":"coastline rising"},{"key":"D","text":"coastline, and rising"}]'::jsonb, 'B', NULL, E'The correct answer is B. The sentence before the blank and the sentence after it are both independent clauses—each has its own subject and verb and expresses a complete thought. A period correctly separates two independent clauses. Choice A creates a comma splice by joining two independent clauses with only a comma. Choice C creates a run-on sentence with no punctuation between the clauses. Choice D incorrectly adds a coordinating conjunction that changes the grammatical relationship, making "rising ocean temperatures" appear to be a second item in a list with "decline."', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q63: RW MCQ Easy — Standard English Conventions / Boundaries
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29HV2XM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city of Bruges, Belgium, was once one of the most important trading centers in medieval Europe ______ its intricate canal system allowed merchants to transport goods directly from the North Sea to warehouses in the city center.', '[{"key":"A","text":"Europe, its"},{"key":"B","text":"Europe its"},{"key":"C","text":"Europe; its"},{"key":"D","text":"Europe. Its intricate canal system, allowed"}]'::jsonb, 'C', NULL, E'The correct answer is C. The clauses on either side of the blank are both independent—each contains a subject and a verb and can stand alone as a sentence. A semicolon is the correct punctuation for joining two closely related independent clauses without a coordinating conjunction. Choice A produces a comma splice by joining two independent clauses with only a comma. Choice B is a run-on sentence with no punctuation between the independent clauses. Choice D correctly uses a period to separate the clauses but introduces an unnecessary comma between the subject ("Its intricate canal system") and its verb ("allowed"), creating a punctuation error within the second sentence.', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q64: RW MCQ Medium — Standard English Conventions / Boundaries
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MZRWMH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethiopian distance runner Derartu Tulu made history in 1992 by becoming the first Black African woman to win an Olympic gold medal ______ she continued to compete at the highest level for over a decade, earning a second Olympic gold in the 10,000 meters at the 2000 Sydney Games.', '[{"key":"A","text":"medal, she"},{"key":"B","text":"medal; she"},{"key":"C","text":"medal she"},{"key":"D","text":"medal. And she"}]'::jsonb, 'B', NULL, E'The correct answer is B. Both the clause before and after the blank are independent clauses. A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. Choice A creates a comma splice by using only a comma between two independent clauses. Choice C produces a run-on sentence with no punctuation. Choice D, while separating the clauses with a period, begins the new sentence with "And," which, though not strictly ungrammatical, is less conventionally correct than the semicolon in formal writing, and the fragment-like feel makes it a weaker choice.', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q65: RW MCQ Medium — Standard English Conventions / Boundaries
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RNQ8MJ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The researchers'' findings pointed to a single unexpected conclusion ______ the high-altitude moss species they had studied was not, as previously assumed, dormant during winter months but was actively photosynthesizing beneath the snow cover.', '[{"key":"A","text":"conclusion:"},{"key":"B","text":"conclusion,"},{"key":"C","text":"conclusion"},{"key":"D","text":"conclusion; that"}]'::jsonb, 'A', NULL, E'The correct answer is A. A colon is the appropriate punctuation when the first independent clause introduces or sets up the information that follows. Here, "a single unexpected conclusion" signals that the next clause will explain what that conclusion is, making the colon the correct boundary marker. Choice B creates a comma splice, since the material after the blank could function as an independent clause. Choice C is a run-on with no punctuation. Choice D incorrectly pairs a semicolon with "that," creating a subordinate clause after a semicolon, which is not conventionally correct—semicolons join independent clauses.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q66: RW MCQ Hard — Standard English Conventions / Boundaries
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WNMFOV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the novelist Gabriela Mistral is best known for her poetry, which earned her the Nobel Prize in Literature in 1945, her lesser-known prose essays on education and child welfare ______ these writings, scholars now argue, helped shape public policy across Latin America during the mid-twentieth century.', '[{"key":"A","text":"were equally influential;"},{"key":"B","text":"were equally influential,"},{"key":"C","text":"were equally influential"},{"key":"D","text":"were equally influential:"}]'::jsonb, 'A', NULL, E'The correct answer is A. The sentence begins with a subordinate clause ("Although...welfare") followed by a main clause that ends at the blank. The material after the blank ("these writings, scholars now argue, helped shape public policy...") is a separate independent clause with its own subject ("these writings") and verb ("helped"). A semicolon correctly separates two independent clauses. Choice B produces a comma splice between two independent clauses. Choice C creates a run-on sentence. Choice D uses a colon, but a colon would require the second clause to explain or elaborate on what precedes it in a definitional or list-like way; here, the second clause introduces new information about the impact of the writings rather than defining "equally influential," making the semicolon the stronger choice. The complexity of the opening subordinate clause and the parenthetical "scholars now argue" in the second clause make the boundary harder to identify.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q67: RW MCQ Easy — Standard English Conventions / Form, Structure, and Sense
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25262WP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of handwoven tapestries displayed in the museum''s east gallery ______ visitors from around the world each year, drawing particular interest from textile historians and art conservators.', '[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]'::jsonb, 'B', NULL, E'The correct answer is B. The subject of the sentence is "collection," which is singular, not "tapestries," which is the object of the preposition "of." A singular subject requires a singular verb form: "attracts." Choice A uses the plural verb form "attract," which does not agree with the singular subject "collection." Choices C and D also use plural verb forms ("have attracted" and "are attracting") that agree with "tapestries" rather than with the true subject "collection."', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q68: RW MCQ Medium — Standard English Conventions / Form, Structure, and Sense
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27WCNI0', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team arrived at the remote wetland site in early March, the migratory cranes ______ their nesting grounds and begun the elaborate courtship displays that characterize the species'' breeding season.', '[{"key":"A","text":"already reached"},{"key":"B","text":"have already reached"},{"key":"C","text":"had already reached"},{"key":"D","text":"will have already reached"}]'::jsonb, 'C', NULL, E'The correct answer is C. The phrase "By the time the conservation team arrived" establishes a past reference point, and the action of the cranes reaching their nesting grounds occurred before that past event. The past perfect tense ("had already reached") is required to indicate an action completed before another past action. Choice A uses the simple past, which fails to convey the sequence of two past events. Choice B uses the present perfect, which connects past actions to the present—inappropriate here since both events are in the past. Choice D uses the future perfect, which is entirely wrong for a past-tense context.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q69: RW MCQ Medium — Standard English Conventions / Form, Structure, and Sense
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EF3O2A', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city''s new sustainability plan calls for reducing carbon emissions by thirty percent, ______ and investing in public transit infrastructure to decrease reliance on personal vehicles.', '[{"key":"A","text":"to convert vacant lots into urban green spaces,"},{"key":"B","text":"converting vacant lots into urban green spaces,"},{"key":"C","text":"the conversion of vacant lots into urban green spaces,"},{"key":"D","text":"vacant lots being converted into urban green spaces,"}]'::jsonb, 'B', NULL, E'The correct answer is B. The sentence contains a series of three actions introduced by the gerund phrases "reducing," "converting," and "investing." Parallel structure requires that all items in a list take the same grammatical form. "Converting" matches the gerund form of "reducing" and "investing." Choice A breaks parallelism by switching to an infinitive ("to convert"). Choice C uses a noun phrase ("the conversion"), which does not match the gerund pattern. Choice D uses a participial construction ("vacant lots being converted") that disrupts the parallel series of gerunds.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q70: RW MCQ Hard — Standard English Conventions / Form, Structure, and Sense
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C002PR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The lead archaeologist noted that although the outer walls of the fortress had crumbled centuries ago, the underground storage chambers, which ______ by a sophisticated ventilation system carved directly into the limestone bedrock, remained structurally sound when the team excavated them in 2019.', '[{"key":"A","text":"were once cooled"},{"key":"B","text":"had once been cooled"},{"key":"C","text":"have once been cooled"},{"key":"D","text":"once cooled"}]'::jsonb, 'B', NULL, E'The correct answer is B. The sentence involves three layers of past time: the crumbling of the walls (distant past), the cooling of the chambers (prior to the excavation), and the excavation in 2019 (a more recent past event). The past perfect ("had once been cooled") is needed to indicate that the ventilation system''s cooling function preceded the 2019 excavation and even the crumbling of the walls. The passive voice is also required because the chambers are being cooled by the ventilation system, not cooling something themselves. Choice A uses the simple past passive, which fails to establish the proper sequence among the three past events. Choice C uses the present perfect passive, which is incorrect in a fully past-tense narrative. Choice D uses "once cooled" as an active verb, which incorrectly suggests the chambers cooled something else rather than being cooled, and also lacks the tense sequencing needed.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q71: RW MCQ Hard — Standard English Conventions / Form, Structure, and Sense
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW211FLV2', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', 'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The review board recommended that the pharmaceutical company ______ all clinical trial data within sixty days, a requirement that reflected growing public demand for transparency in drug approval processes.', '[{"key":"A","text":"releases"},{"key":"B","text":"released"},{"key":"C","text":"release"},{"key":"D","text":"would release"}]'::jsonb, 'C', NULL, E'The correct answer is C. The verb "recommended" triggers the subjunctive mood in the "that" clause that follows. In English, the subjunctive after verbs of recommendation, demand, or suggestion requires the base form of the verb (without any inflection), regardless of the subject. "Release" is the bare infinitive form required by the subjunctive construction "recommended that [subject] [base form]." Choice A uses the third-person singular present indicative "releases," which would be standard in a declarative sentence but is incorrect in a subjunctive clause. Choice B uses the past tense "released," which some speakers substitute informally but is not the standard subjunctive form in formal English. Choice D uses "would release," a conditional construction that is sometimes used in British English as an alternative to the subjunctive but is not the conventionally correct American English form tested on the SAT.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);


-- ═══════════════════════════════════════════════════════════
