-- Q72: RW MCQ Easy — Expression of Ideas / Transitions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VVBALL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', 'Which choice completes the text with the most logical transition?', E'The Brazilian three-banded armadillo is the only armadillo species that can roll itself into a complete ball as a defense mechanism. ______ all other armadillo species must rely on burrowing into the ground to escape predators.', '[{"key":"A","text":"In addition,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"For example,"},{"key":"D","text":"Accordingly,"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage sets up a distinction between the Brazilian three-banded armadillo, which can roll into a ball, and all other armadillo species, which must burrow. "By contrast" is the appropriate transition because the second sentence presents a difference from what the first sentence describes. "In addition" (A) incorrectly signals that more similar information is being added. "For example" (C) incorrectly treats the second sentence as an illustration of the first. "Accordingly" (D) incorrectly implies a cause-effect relationship.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q73: RW MCQ Medium — Expression of Ideas / Transitions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A9YC1O', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', 'Which choice completes the text with the most logical transition?', E'Urban planners in Copenhagen spent decades redesigning city streets to prioritize cycling infrastructure over automobile traffic. ______ the city now has more than 390 kilometers of designated bike lanes, and over 60 percent of residents commute by bicycle daily.', '[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Granted,"},{"key":"C","text":"As a result,"},{"key":"D","text":"On the other hand,"}]'::jsonb, 'C', NULL, E'The correct answer is C. The second sentence describes the outcome of Copenhagen''s decades-long investment in cycling infrastructure: extensive bike lanes and high rates of bicycle commuting. "As a result" correctly signals that these outcomes follow from the planning efforts described in the first sentence. "Nevertheless" (A) and "On the other hand" (D) both incorrectly suggest a contrast or concession, when the second sentence is actually a logical consequence. "Granted" (B) is used to acknowledge an opposing point before countering it, which does not fit the relationship between these sentences.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q74: RW MCQ Medium — Expression of Ideas / Transitions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22GRQV7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', 'Which choice completes the text with the most logical transition?', E'Restoring coral reefs involves several carefully timed stages. First, marine biologists collect fragments of healthy coral from donor colonies. Next, they cultivate these fragments in underwater nurseries for six to twelve months. ______ the mature fragments are transplanted onto degraded reef structures, where they are monitored for signs of attachment and growth.', '[{"key":"A","text":"In other words,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Finally,"},{"key":"D","text":"However,"}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage describes a multi-step process in sequence: collecting fragments, cultivating them, and then transplanting them. The word "Finally" correctly signals the last step in this sequence, following "First" and "Next." "In other words" (A) would indicate a restatement, not a new step. "Similarly" (B) would suggest a parallel action rather than the next stage. "However" (D) would introduce a contrast, which is inconsistent with the sequential structure of the passage.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q75: RW MCQ Hard — Expression of Ideas / Transitions
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28DIRKE', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', 'Which choice completes the text with the most logical transition?', E'Some historians have argued that the printing press was the primary catalyst for the Protestant Reformation, since it enabled the rapid distribution of dissenting theological texts. While the press undeniably accelerated the spread of reformist ideas, recent scholarship suggests that widespread popular discontent with ecclesiastical taxation had already created fertile conditions for religious upheaval. The printing press, ______ did not so much ignite the Reformation as amplify grievances that were already deeply felt.', '[{"key":"A","text":"moreover,"},{"key":"B","text":"then,"},{"key":"C","text":"instead,"},{"key":"D","text":"nevertheless,"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage builds an argument that concedes the importance of the printing press but repositions its role: rather than being the primary catalyst, it amplified existing discontent. The word "then" functions here to signal a logical conclusion drawn from the preceding reasoning—given that discontent already existed, the press therefore served as an amplifier rather than an originator. "Moreover" (A) would add a new, parallel point rather than draw a conclusion. "Instead" (C) is tempting but too strong; the passage does not fully reject the role of the printing press but rather recharacterizes it, and "instead" would imply complete substitution. "Nevertheless" (D) would introduce a concession or contrast, but the final sentence is drawing a conclusion consistent with the argument, not contrasting against it.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q76: RW MCQ Easy — Expression of Ideas / Rhetorical Synthesis
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27ZI1ZN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a summary about honeybee communication for a biology class. The student wants to emphasize what the waggle dance communicates to other bees. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'- Honeybees use a behavior called the waggle dance to share information with other members of the hive.\n- During the dance, a bee moves in a figure-eight pattern on the surface of the honeycomb.\n- The angle of the dance relative to the vertical indicates the direction of a food source in relation to the sun.\n- The duration of the waggle portion of the dance indicates the distance to the food source.\n- The waggle dance was first decoded by Austrian ethologist Karl von Frisch in 1967.', '[{"key":"A","text":"The waggle dance, a figure-eight movement performed on the honeycomb, was first decoded by Karl von Frisch in 1967."},{"key":"B","text":"Through the waggle dance, honeybees communicate both the direction and the distance of a food source to other members of the hive."},{"key":"C","text":"Honeybees perform a behavior known as the waggle dance, which involves moving in a figure-eight pattern on the honeycomb surface."},{"key":"D","text":"Karl von Frisch, an Austrian ethologist, discovered that honeybees use a waggle dance to share information with their hive."}]'::jsonb, 'B', NULL, E'The correct answer is B. The student''s goal is to emphasize what the waggle dance communicates. Option B directly states the two pieces of information conveyed by the dance—direction and distance of a food source—making it the most effective choice. Option A (A) focuses on the physical movement and the historical discovery rather than what is communicated. Option C (C) describes the physical pattern of the dance but does not mention what information it conveys. Option D (D) centers on the discoverer rather than the content of the communication.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q77: RW MCQ Medium — Expression of Ideas / Rhetorical Synthesis
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MCAH02', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research report about urban heat islands. The student wants to highlight the difference in temperature between urban and rural areas. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'- Urban heat islands occur when cities experience significantly higher temperatures than surrounding rural areas.\n- Paved surfaces such as asphalt and concrete absorb and retain more solar radiation than natural landscapes do.\n- A 2023 study of 150 U.S. cities found that urban centers were on average 2.9 degrees Celsius warmer than nearby rural regions during summer months.\n- Green infrastructure, such as urban tree canopies and rooftop gardens, can reduce local temperatures by 1 to 5 degrees Celsius.\n- The urban heat island effect is most pronounced at night, when built surfaces slowly release stored heat.', '[{"key":"A","text":"Green infrastructure like tree canopies and rooftop gardens can lower urban temperatures by 1 to 5 degrees Celsius, helping to mitigate the urban heat island effect."},{"key":"B","text":"A 2023 study of 150 U.S. cities revealed that urban centers were on average 2.9 degrees Celsius warmer than nearby rural areas during summer, illustrating the measurable temperature gap produced by urban heat islands."},{"key":"C","text":"The urban heat island effect is most noticeable at night because paved surfaces such as asphalt and concrete slowly release the solar radiation they absorbed during the day."},{"key":"D","text":"Because asphalt and concrete absorb more solar radiation than natural landscapes, cities that lack green infrastructure are especially vulnerable to rising temperatures."}]'::jsonb, 'B', NULL, E'The correct answer is B. The student''s goal is to highlight the temperature difference between urban and rural areas. Option B directly presents the quantitative finding from the 2023 study—a 2.9-degree Celsius difference—and explicitly frames it as a comparison between urban centers and nearby rural areas. Option A (A) focuses on mitigation strategies rather than the urban-rural temperature gap. Option C (C) discusses when the effect is most pronounced and why, but does not compare urban and rural temperatures. Option D (D) explains a cause of heat absorption and vulnerability but does not present the specific temperature difference between urban and rural settings.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

-- Q78: RW MCQ Hard — Expression of Ideas / Rhetorical Synthesis
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HO8A1M', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article about the cassowary for an ecology journal. The student wants to emphasize the cassowary''s ecological importance rather than its physical characteristics. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'- The southern cassowary is a large flightless bird native to the tropical rainforests of northeastern Australia and New Guinea.\n- Adults can stand up to 1.8 meters tall and weigh as much as 76 kilograms, making the cassowary the third-heaviest living bird.\n- Cassowaries consume over 240 species of rainforest fruit and disperse the seeds through their droppings across wide territories.\n- Some rainforest tree species produce fruits too large for any other native animal to swallow whole, meaning these trees depend almost entirely on cassowaries for seed dispersal.\n- Declining cassowary populations have been linked to reduced seedling recruitment in several rainforest tree species that lack alternative dispersal agents.', '[{"key":"A","text":"The southern cassowary, the third-heaviest living bird, can stand up to 1.8 meters tall and consumes over 240 species of rainforest fruit across its range in northeastern Australia and New Guinea."},{"key":"B","text":"Because some rainforest trees produce fruits too large for other animals to swallow, cassowaries serve as the sole seed dispersers for these species, and declining cassowary populations have consequently been linked to reduced seedling recruitment in those trees."},{"key":"C","text":"Native to the tropical rainforests of northeastern Australia and New Guinea, cassowaries disperse seeds of over 240 fruit species, making them the third-heaviest living bird."},{"key":"D","text":"Declining cassowary populations are a concern because the southern cassowary, which can weigh up to 76 kilograms, is one of the largest flightless birds in the world."}]'::jsonb, 'B', NULL, E'The correct answer is B. The student''s goal is to emphasize the cassowary''s ecological importance rather than its physical characteristics. Option B focuses entirely on the bird''s irreplaceable role in seed dispersal: certain trees depend solely on cassowaries because their fruits are too large for other animals, and population declines have measurably reduced seedling recruitment. This directly addresses ecological function and consequence. Option A (A) leads with physical traits (height, weight, ranking among birds) and only mentions fruit consumption without explaining its ecological significance. Option C (C) conflates seed dispersal with the bird''s physical size in a way that illogically presents weight as a consequence of dispersal behavior. Option D (D) frames the concern around the cassowary''s physical size rather than its ecological function, making the reason for concern its largeness rather than its role in the ecosystem.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-01"}'::jsonb, '{"model":"claude","generation_date":"2026-07-01","prompt_version":"questions_governance_v1"}'::jsonb);

